await bash('cd /workspace && python3 - <<'EOF'
import statistics
import numpy as np
import random as pyrandom

def buggy(xs, k=3.0):
    out = []
    for i in range(len(xs)):
        w = xs[max(0,i-30):i+30]
        mu, sd = statistics.mean(w), statistics.pstdev(w)
        if abs(xs[i]-mu) > k*sd:
            out.append(i)
    return set(out)

def gen(kind):
    if kind == 'pyrandom':
        r = pyrandom.Random(15); return [r.gauss(0,1) for _ in range(500)]
    if kind == 'np_legacy':
        return list(np.random.RandomState(15).normal(0,1,500))
    if kind == 'np_default':
        return list(np.random.default_rng(15).normal(0,1,500))

for kind in ('pyrandom','np_legacy','np_default'):
    xs = gen(kind)
    for i in range(250,254): xs[i] += 10.0
    hits = buggy(xs)
    missed = [i for i in range(250,254) if i not in hits]
    # lookahead: does zeroing suffix change any decision at i < cut?
    diffs = []
    for cut in range(1,500):
        m = xs[:cut] + [0.0]*(500-cut)
        b = {i for i in buggy(xs) if i < cut}
        a = {i for i in buggy(m) if i < cut}
        if a != b:
            diffs.append((cut, sorted(b-a), sorted(a-b)))
    print(f"{kind}: missed={missed}, lookahead cuts={len(diffs)}, first={diffs[:2]}")
EOF')

