import statistics, math, random as pyrandom

def buggy(xs, k=3.0):
    out = []
    for i in range(len(xs)):
        w = xs[max(0,i-30):i+30]
        mu = sum(w)/len(w)
        var = sum((v-mu)**2 for v in w)/len(w)
        if abs(xs[i]-mu) > k*math.sqrt(var):
            out.append(i)
    return set(out)

def gen(kind):
    if kind == 'pyrandom':
        r = pyrandom.Random(15); return [r.gauss(0,1) for _ in range(500)]
    if kind == 'pyrandom_seed15_normalvariate':
        r = pyrandom.Random(15); return [r.normalvariate(0,1) for _ in range(500)]
    if kind == 'pyrandom_unseeded_repr':
        return None

for kind in ('pyrandom','pyrandom_seed15_normalvariate'):
    r_xs = gen(kind)
    xs = list(r_xs)
    for i in range(250,254): xs[i] += 10.0
    hits = buggy(xs)
    missed = [i for i in range(250,254) if i not in hits]
    diffs = []
    for cut in range(240, 270):
        m = xs[:cut] + [0.0]*(500-cut)
        b = {i for i in buggy(xs) if i < cut}
        a = {i for i in buggy(m) if i < cut}
        if a != b:
            diffs.append((cut, sorted(b-a), sorted(a-b)))
    print(f"{kind}: missed={missed}, lookahead cuts={len(diffs)}, first={diffs[:2]}")
EOF')

