import math, random, statistics

def buggy(xs, k=3.0):
    out=[]
    for i in range(len(xs)):
        w = xs[max(0,i-30):i+30]
        if abs(xs[i]-statistics.mean(w)) > k*statistics.pstdev(w): out.append(i)
    return set(out)

def gen_bm(seed):
    r = random.Random(seed)
    def normals():
        while True:
            u1 = r.random(); u2 = r.random()
            if u1 <= 1e-12: continue
            z0 = math.sqrt(-2*math.log(u1))*math.cos(2*math.pi*u2)
            yield z0
            z1 = math.sqrt(-2*math.log(u1))*math.sin(2*math.pi*u2)
            yield z1
    g = normals(); return [next(g) for _ in range(500)]

